export function getApiVersionKey() {
  return ['{apiVersion}'] as const
}

export function getApiVersionAccountQueryKey(
  args: InferRequestType<(typeof client)[':apiVersion']['account']['$get']>,
) {
  return [':apiVersion', '/:apiVersion/account', args] as const
}

export function getApiVersionAccountQueryOptions<
  TData = Awaited<
    ReturnType<
      typeof parseResponse<Awaited<ReturnType<(typeof client)[':apiVersion']['account']['$get']>>>
    >
  >,
  TError = DefaultError,
>(
  args: InferRequestType<(typeof client)[':apiVersion']['account']['$get']>,
  options?: ClientRequestOptions,
) {
  return queryOptions<
    Awaited<
      ReturnType<
        typeof parseResponse<Awaited<ReturnType<(typeof client)[':apiVersion']['account']['$get']>>>
      >
    >,
    TError,
    TData,
    ReturnType<typeof getApiVersionAccountQueryKey>
  >({
    queryKey: getApiVersionAccountQueryKey(args),
    queryFn({ signal }) {
      return parseResponse(
        client[':apiVersion'].account.$get(args, {
          ...options,
          init: { ...options?.init, signal },
        }),
      )
    },
  })
}

